arguments.command:
cd /app/submission && python3 - <<'EOF'
src = open('main.py').read()
start = src.index("def parse_inputs(")
end = src.index("def expected_sums(")
new = '''def parse_inputs(v):
    """validated rectangular P x R x D array -> (P, R, D, data)"""
    if type(v) is not list:
        raise Err("E_SCHEMA")
    P = len(v)
    if P < 1 or P > 8:
        raise Err("E_LIMIT")
    R = None
    for row in v:
        if type(row) is not list:
            raise Err("E_SCHEMA")
        if R is None:
            R = len(row)
        elif len(row) != R:
            raise Err("E_SCHEMA")
    if R > 128:
        raise Err("E_LIMIT")
    D = None
    for row in v:
        for vec in row:
            if type(vec) is not list:
                raise Err("E_SCHEMA")
            if D is None:
                D = len(vec)
            elif len(vec) != D:
                raise Err("E_SCHEMA")
    if D > 32:
        raise Err("E_LIMIT")
    for row in v:
        for vec in row:
            if vec:
                if not all(type(x) is int for x in vec):
                    raise Err("E_SCHEMA")
                if min(vec) < -1000000000 or max(vec) > 1000000000:
                    raise Err("E_LIMIT")
    return P, R, D, v


'''
open('main.py','w').write(src[:start] + new + src[end:])
EOF
grep -n "^def \|^class " main.py
